const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');
const crypto = require('crypto');

const db = new Database('/workspace/world.db');

// Generate a UUID
const reminderId = crypto.randomUUID();
const content = \"Follow up with Maya if she's not there by 6:30 PM.\";
const reminderTimestamp = 1803033000.0;
const creationTimestamp = Date.now() / 1000;

// Insert the reminder
db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)').run(
  reminderId, content, creationTimestamp, reminderTimestamp, null, null
);

// Verify it was inserted
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log(JSON.stringify({ok: true, result: row}, null, 2));

db.close();
"

